type DispatchRole = "Owner" | "Dispatcher" | "Technician";
type DispatchView =
  | "Dashboard"
  | "Jobs"
  | "Work Orders"
  | "Payments"
  | "GPS Map"
  | "Analytics"
  | "AI Agents"
  | "Equipment"
  | "Team"
  | "Settings";

type DispatchJob = {
  id: string;
  time: string;
  customer: string;
  service: string;
  address: string;
  tech: string;
  techId: string | null;
  customerId: string;
  status: string;
  revenueCents: number;
  revenue: string;
  eta: string;
  color: string;
  lat: number | null;
  lng: number | null;
};
type DispatchCustomer = { id: string; name: string; phone: string | null; email: string | null };
type DispatchTechnician = { id: string; name: string; role: string; active_jobs: number };

function jobColor(status: string) {
  if (status === "IN PROGRESS") return "red";
  if (status === "ASSIGNED") return "amber";
  if (status === "BOOKED") return "green";
  return "blue";
}
function mapDispatchJob(row: Record<string, unknown>): DispatchJob {
  const scheduled = row.scheduled_at ? new Date(String(row.scheduled_at)) : null;
  return {
    id: String(row.id),
    time: scheduled ? scheduled.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" }) : "—",
    customer: String(row.customer_name || "Unknown customer"),
    service: String(row.service_type || ""),
    address: String(row.address || ""),
    tech: String(row.tech_name || "Unassigned"),
    techId: row.assigned_tech_id ? String(row.assigned_tech_id) : null,
    customerId: String(row.customer_id || ""),
    status: String(row.status || "BOOKED"),
    revenueCents: Number(row.revenue_cents || 0),
    revenue: `$${(Number(row.revenue_cents || 0) / 100).toLocaleString()}`,
    eta: String(row.status) === "COMPLETE" || String(row.status) === "INVOICED" ? "Done" : "Not routed",
    color: jobColor(String(row.status || "BOOKED")),
    lat: typeof row.lat === "number" ? row.lat : null,
    lng: typeof row.lng === "number" ? row.lng : null,
  };
}
function dispatchPins(jobs: DispatchJob[]): MapPin[] {
  return jobs
    .filter((job) => job.lat != null && job.lng != null)
    .map((job, index) => ({
      id: job.id,
      lat: job.lat as number,
      lng: job.lng as number,
      label: `${job.time} · ${job.customer}`,
      sublabel: `${job.service} · ${job.status}${job.tech !== "Unassigned" ? ` · ${job.tech}` : ""}`,
      badge: index + 1,
      tone: job.status === "IN PROGRESS" ? "red" : job.status === "ASSIGNED" ? "amber" : job.status === "BOOKED" ? "green" : "blue",
    }));
}

function CyncroDispatch({ onNavigate }: { onNavigate?: (t: Tab) => void } = {}) {
  const [authenticated, setAuthenticated] = useState(false);
  const [checkingSession, setCheckingSession] = useState(true);
  const [role, setRole] = useState<DispatchRole>("Owner");
  const [view, setView] = useState<DispatchView>("Dashboard");
  const [notice, setNotice] = useState("");
  const [jobs, setJobs] = useState<DispatchJob[]>([]);
  const [customers, setCustomers] = useState<DispatchCustomer[]>([]);
  const [technicians, setTechnicians] = useState<DispatchTechnician[]>([]);
  const [selectedJob, setSelectedJob] = useState(0);
  const [techStatus, setTechStatus] = useState("EN ROUTE");
  const [loginEmail, setLoginEmail] = useState("");
  const [jobModalOpen, setJobModalOpen] = useState(false);
  const flash = (message: string) => {
    setNotice(message);
    window.setTimeout(() => setNotice(""), 1800);
  };
  const geocodeAttempts = useRef(0);
  const loadJobs = () => {
    void fetch("/api/dispatch/jobs").then((r) => (r.ok ? r.json() : null)).then((data: { jobs?: Record<string, unknown>[] } | null) => {
      if (!data?.jobs) return;
      const mapped = data.jobs.map(mapDispatchJob);
      setJobs(mapped);
      if (mapped.some((job) => job.lat == null && job.address) && geocodeAttempts.current < 4) {
        geocodeAttempts.current += 1;
        void fetch("/api/dispatch/geocode", { method: "POST" })
          .then((r) => (r.ok ? r.json() : null))
          .then((result: { geocoded?: number } | null) => { if (result?.geocoded) loadJobs(); });
      }
    });
  };
  const loadCustomers = () => {
    void fetch("/api/dispatch/customers").then((r) => (r.ok ? r.json() : null)).then((data: { customers?: DispatchCustomer[] } | null) => {
      if (data?.customers) setCustomers(data.customers);
    });
  };
  const loadTechnicians = () => {
    void fetch("/api/dispatch/technicians").then((r) => (r.ok ? r.json() : null)).then((data: { technicians?: DispatchTechnician[] } | null) => {
      if (data?.technicians) setTechnicians(data.technicians);
    });
  };
  useEffect(() => {
    void fetch("/api/auth/me").then((r) => {
      if (r.ok) {
        setAuthenticated(true);
        loadJobs();
        loadCustomers();
        loadTechnicians();
      }
      setCheckingSession(false);
    });
  }, []);
  const login = (nextRole: DispatchRole) => {
    setRole(nextRole);
    setAuthenticated(true);
    setView(nextRole === "Technician" ? "Jobs" : "Dashboard");
    loadJobs();
    loadCustomers();
    loadTechnicians();
    flash(`${nextRole} workspace unlocked`);
  };
  const moveJob = (index: number, direction: number) => {
    const target = index + direction;
    if (target < 0 || target >= jobs.length) return;
    const next = [...jobs];
    [next[index], next[target]] = [next[target], next[index]];
    setJobs(next);
    setSelectedJob(target);
    flash("Route order updated locally · optimization not yet automated");
  };
  const createJob = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    const customerName = String(data.get("customer") || "").trim();
    const service = String(data.get("service") || "").trim();
    const address = String(data.get("address") || "").trim();
    const time = String(data.get("time") || "09:00");
    const revenue = Number(data.get("revenue") || 0);
    const techId = String(data.get("tech") || "");
    if (!customerName || !service || !address) {
      flash("Customer, service, and address are required");
      return;
    }
    void (async () => {
      let customerId = customers.find((c) => c.name.toLowerCase() === customerName.toLowerCase())?.id;
      if (!customerId) {
        const res = await fetch("/api/dispatch/customers", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ name: customerName, address }),
        });
        if (!res.ok) { flash("Unable to create customer"); return; }
        const created = await res.json() as { id: string };
        customerId = created.id;
        loadCustomers();
      }
      const scheduledAt = new Date();
      const [h, m] = time.split(":").map(Number);
      scheduledAt.setHours(h || 9, m || 0, 0, 0);
      const res = await fetch("/api/dispatch/jobs", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          customerId, serviceType: service, address, scheduledAt: scheduledAt.toISOString(),
          revenue, assignedTechId: techId || undefined,
        }),
      });
      if (!res.ok) { flash("Unable to create job"); return; }
      const created = await res.json() as { id: string };
      loadJobs();
      loadTechnicians();
      setView("Jobs");
      setJobModalOpen(false);
      flash(`Job created`);
      void created;
    })();
  };
  const advanceJob = (index: number) => {
    const lifecycle = ["BOOKED", "ASSIGNED", "IN PROGRESS", "COMPLETE", "INVOICED"];
    const job = jobs[index];
    if (!job) return;
    const next = lifecycle[Math.min(lifecycle.indexOf(job.status) + 1, lifecycle.length - 1)];
    void fetch("/api/dispatch/jobs", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ id: job.id, status: next }),
    }).then((r) => {
      if (r.ok) { loadJobs(); flash("Job status advanced"); }
      else flash("Unable to update job");
    });
  };
  const cancelJob = (index: number) => {
    const job = jobs[index];
    if (!job) return;
    void fetch(`/api/dispatch/jobs?id=${encodeURIComponent(job.id)}`, { method: "DELETE" }).then((r) => {
      if (r.ok) { loadJobs(); setSelectedJob(0); flash("Job cancelled"); }
      else flash("Unable to cancel job");
    });
  };

  if (checkingSession) return null;
  if (!authenticated) {
    return (
      <section className="dispatchGate">
        {notice && <div className="dispatchToast">✓ {notice}</div>}
        <div className="dispatchGateGlow" />
        <div className="dispatchGateCopy">
          <span>CYNCRO FIELD OPERATIONS</span>
          <h1>
            Cyncro <i>Dispatch</i>
          </h1>
          <p>
            The command system for contractors—jobs, crews, GPS, routes,
            customers, revenue, and AI agents operating as one.
          </p>
          <div className="dispatchGateProof">
            <span>◆ Live field visibility</span>
            <span>◆ AI booking + follow-up</span>
            <span>◆ Profit on every job</span>
          </div>
          <div
            className="dispatchProductPreview"
            aria-label="Dispatch live operation preview"
          >
            <header>
              <span>LIVE FIELD OPERATION</span>
              <b>4 crews active</b>
            </header>
            <div className="miniDispatchMap">
              <i className="miniRoute routeOne" />
              <i className="miniRoute routeTwo" />
              {[
                ["AC", "22%", "63%"],
                ["MT", "58%", "28%"],
                ["DS", "76%", "71%"],
              ].map((tech) => (
                <button style={{ left: tech[1], top: tech[2] }} key={tech[0]}>
                  {tech[0]}
                  <small>● moving</small>
                </button>
              ))}
              <span className="miniJob one">1</span>
              <span className="miniJob two">2</span>
              <span className="miniJob three">3</span>
            </div>
            <footer>
              <div>
                <small>BOOKED TODAY</small>
                <b>$9,425</b>
              </div>
              <div>
                <small>ON-TIME RATE</small>
                <b>96.8%</b>
              </div>
              <div>
                <small>DRIVE TIME SAVED</small>
                <b>2h 14m</b>
              </div>
            </footer>
          </div>
        </div>

        <aside className="dispatchLoginCard">
          <div className="dispatchMark">D</div>
          <small>CONTRACTOR ACCESS</small>
          <h2>Enter Dispatch</h2>
          <p>Separate, secure access for every company and field role.</p>
          <label>
            Work email
            <input
              value={loginEmail}
              onChange={(event) => setLoginEmail(event.target.value)}
              placeholder="you@company.com"
            />
          </label>
          <label>
            Password
            <input
              type="password"
              defaultValue="dispatch2026"
              aria-label="Dispatch password"
            />
          </label>
          <button className="dispatchSignIn" onClick={() => login("Owner")}>
            Sign in to Dispatch →
          </button>
          <button
            className="dispatchSSO"
            onClick={() => flash("SSO is not connected yet — no identity provider configured")}
          >
            Continue with company SSO
          </button>
          <div className="demoRolePicker">
            <span>EXPLORE ROLE DEMOS</span>
            <div>
              {(["Owner", "Dispatcher", "Technician"] as DispatchRole[]).map(
                (item) => (
                  <button onClick={() => login(item)} key={item}>
                    {item}
                  </button>
                ),
              )}
            </div>
          </div>
          <div className="dispatchPlan">
            <div>
              <small>DISPATCH PROFESSIONAL</small>
              <b>
                $249<em>/month</em>
              </b>
            </div>
            <span>Up to 10 technicians · Cancel anytime</span>
            <button onClick={() => flash("Billing is not connected yet — no payment processor configured")}>
              Start contractor account
            </button>
          </div>
          <footer>
            Protected by role-based access · Your crews only see assigned work.
          </footer>
        </aside>
      </section>
    );
  }

  if (role === "Technician") {
    return (
      <section className="techAppStage">
        {notice && <div className="dispatchToast">✓ {notice}</div>}
        <div className="techStageCopy">
          <button
            className="backToDispatch"
            onClick={() => setAuthenticated(false)}
          >
            ← Contractor login
          </button>
          <span>CYNCRO DISPATCH · TECH APP</span>
          <h1>
            Built for the field.
            <br />
            Impossible to mess up.
          </h1>
          <p>
            Only today’s assigned work, the fastest route, clear job steps, and
            one-tap proof of completion.
          </p>
          <div className="offlineReady">
            <i>✓</i>
            <div>
              <b>Offline ready</b>
              <small>
                Jobs, photos, notes, and signatures sync when service returns.
              </small>
            </div>
          </div>
          <div className="techDemoControls">
            <button onClick={() => setTechStatus("ARRIVED")}>
              Simulate arrival
            </button>
            <button onClick={() => setTechStatus("COMPLETE")}>
              Complete job
            </button>
            <button
              onClick={() => {
                setRole("Owner");
                setView("Dashboard");
              }}
            >
              Open owner view
            </button>
          </div>
        </div>
        <div className="phoneShell">
          <div className="phoneBar">
            <span>9:41</span>
            <i>● ● ◼</i>
          </div>
          <header>
            <div>
              <small>THURSDAY · AUG 13</small>
              <h2>Good morning, Andre.</h2>
            </div>
            <span>AC</span>
          </header>
          <div className="techStatusStrip">
            <i>●</i>
            <span>
              <b>
                {techStatus === "COMPLETE"
                  ? "Job completed"
                  : techStatus === "ARRIVED"
                    ? "You’ve arrived at Job 1"
                    : "Route optimized"}
              </b>
              <small>
                {techStatus === "COMPLETE"
                  ? "Invoice + owner SMS sent"
                  : techStatus === "ARRIVED"
                    ? "Geofence verified · Timer started"
                    : "31 minutes of drive time saved"}
              </small>
            </span>
          </div>
          <nav>
            <button className="active">Today</button>
            <button onClick={() => flash("Route map opened")}>Route</button>
            <button onClick={() => flash("Tech profile opened")}>
              Profile
            </button>
          </nav>
          <main>
            <div className="nextJobLabel">
              <span>NEXT JOB</span>
              <em>1 OF 3</em>
            </div>
            <article className="mobileJobCard">
              <div className="mobileJobMap">
                <span>AC</span>
                <i>1</i>
                <em>8 min · 3.2 mi</em>
              </div>
              <div className="mobileJobBody">
                <small>
                  {jobs[0].id} · {jobs[0].time}
                </small>
                <h3>{jobs[0].customer}</h3>
                <p>{jobs[0].service}</p>
                <address>{jobs[0].address}</address>
                <div>
                  <button
                    onClick={() => flash("Turn-by-turn navigation opened")}
                  >
                    Navigate
                  </button>
                  <button onClick={() => setTechStatus("ARRIVED")}>
                    {techStatus === "ARRIVED" ? "✓ Arrived" : "I’ve arrived"}
                  </button>
                </div>
              </div>
            </article>
            <div className="workOrderMobile">
              <header>
                <span>WORK ORDER</span>
                <b>Scope + customer notes</b>
              </header>
              <p>
                Diagnose audio zones, calibrate speakers, verify network
                control, and demonstrate final settings to customer.
              </p>
              <button onClick={() => flash("Before photo captured")}>
                ＋ Before photo
              </button>
              <button onClick={() => flash("Field note saved")}>
                ＋ Add note
              </button>
              <button onClick={() => flash("Signature captured")}>
                ✎ Capture signature
              </button>
            </div>
            <button
              className="completeMobileJob"
              onClick={() => {
                setTechStatus("COMPLETE");
                flash("Job complete · Invoice and SMS triggered");
              }}
            >
              Mark job complete
            </button>
          </main>
          <footer>
            <button className="active">
              ▦<small>Jobs</small>
            </button>
            <button>
              ⌖<small>Route</small>
            </button>
            <button>
              ◎<small>Account</small>
            </button>
          </footer>
        </div>
      </section>
    );
  }

  const navItems: { name: DispatchView; icon: string }[] = [
    { name: "Dashboard", icon: "⌂" },
    { name: "Jobs", icon: "▦" },
    { name: "Work Orders", icon: "▤" },
    { name: "Payments", icon: "$" },
    { name: "GPS Map", icon: "⌖" },
    { name: "Analytics", icon: "⌁" },
    { name: "AI Agents", icon: "✦" },
    { name: "Equipment", icon: "◇" },
    { name: "Team", icon: "◎" },
    { name: "Settings", icon: "⚙" },
  ];
  return (
    <section className="dispatchShell">
      {notice && <div className="dispatchToast">✓ {notice}</div>}
      {jobModalOpen && (
        <div className="dispatchModalBackdrop" role="presentation">
          <form className="dispatchModal" onSubmit={createJob}>
            <header>
              <div>
                <small>JOB COMMAND</small>
                <h2>Create a field job</h2>
              </div>
              <button
                type="button"
                onClick={() => setJobModalOpen(false)}
                aria-label="Close new job form"
              >
                ×
              </button>
            </header>
            <label>
              Customer
              <input
                name="customer"
                placeholder="Customer or company"
                required
              />
            </label>
            <label>
              Service
              <input name="service" placeholder="Service requested" required />
            </label>
            <label>
              Job address
              <input
                name="address"
                placeholder="Full service address"
                required
              />
            </label>
            <div>
              <label>
                Time
                <input name="time" type="time" defaultValue="09:00" required />
              </label>
              <label>
                Estimated revenue
                <input
                  name="revenue"
                  type="number"
                  min="0"
                  step="1"
                  defaultValue="500"
                />
              </label>
            </div>
            <label>
              Assign technician
              <select name="tech" defaultValue="">
                <option value="">Unassigned</option>
                {technicians.map((t) => (
                  <option value={t.id} key={t.id}>{t.name}</option>
                ))}
              </select>
            </label>
            <footer>
              <button type="button" onClick={() => setJobModalOpen(false)}>
                Cancel
              </button>
              <button type="submit">Create job →</button>
            </footer>
          </form>
        </div>
      )}
      <aside className="dispatchSidebar">
        <div className="dispatchBrand">
          <span>D</span>
          <div>
            <b>Cyncro Dispatch</b>
            <small>CTS Audio Video</small>
          </div>
        </div>
        <div className="dispatchRole">
          <small>ACTIVE WORKSPACE</small>
          <button
            onClick={() => setRole(role === "Owner" ? "Dispatcher" : "Owner")}
          >
            <span>{role === "Owner" ? "YL" : "DP"}</span>
            <div>
              <b>{role}</b>
              <small>
                {role === "Owner" ? "Full company access" : "Field operations"}
              </small>
            </div>
            <i>⌄</i>
          </button>
        </div>
        <nav>
          {navItems
            .filter(
              (item) =>
                role === "Owner" ||
                !["Analytics", "Payments", "Settings"].includes(item.name),
            )
            .map((item) => (
              <button
                className={view === item.name ? "active" : ""}
                onClick={() => setView(item.name)}
                key={item.name}
              >
                <i>{item.icon}</i>
                <span>{item.name}</span>
                {item.name === "Jobs" && <em>{jobs.length}</em>}
              </button>
            ))}
        </nav>
        <div className="dispatchSideSystem">
          <small>CONNECTED PLATFORM</small>
          <button onClick={() => onNavigate ? onNavigate("crm") : (window.location.hash = "#crm")}>
            <i>◫</i>
            <span>Cyncro CRM</span>
            <em>↗</em>
          </button>
          <button onClick={() => onNavigate ? onNavigate("admin") : (window.location.hash = "#admin")}>
            <i>□</i>
            <span>Calendar</span>
            <em>↗</em>
          </button>
        </div>
        <div className="dispatchSubscription">
          <span>PRO</span>
          <div>
            <b>Dispatch Professional</b>
            <small>$249/mo · 7 of 10 techs</small>
          </div>
          <button onClick={() => setAuthenticated(false)}>•••</button>
        </div>
      </aside>
      <main className="dispatchMain">
        <header className="dispatchTopbar">
          <div>
            <small>THURSDAY, AUGUST 13</small>
            <b>{view === "Dashboard" ? `${role} Command Center` : view}</b>
          </div>
          <div>
            <button onClick={() => {
              const q = window.prompt("Search jobs by customer or service type");
              if (!q) return;
              const matches = jobs.filter((j) => j.customer.toLowerCase().includes(q.toLowerCase()) || j.service.toLowerCase().includes(q.toLowerCase()));
              if (!matches.length) { flash(`No jobs match "${q}"`); return; }
              setSelectedJob(jobs.indexOf(matches[0]));
              setView("Jobs");
              flash(`${matches.length} job(s) match "${q}"`);
            }}>⌕</button>
            <button onClick={() => flash("No dispatch alerts")}>
              ◌<i />
            </button>
            <button onClick={() => setJobModalOpen(true)}>＋ New job</button>
          </div>
        </header>
        <div className="dispatchContent">
          {view === "Dashboard" && (
            <DispatchDashboard
              jobs={jobs}
              onView={setView}
              onFlash={flash}
              onMove={moveJob}
              role={role}
              onReload={() => { loadJobs(); loadCustomers(); loadTechnicians(); }}
            />
          )}
          {view === "Jobs" && (
            <DispatchJobs
              jobs={jobs}
              selected={selectedJob}
              setSelected={setSelectedJob}
              onFlash={flash}
              onNew={() => setJobModalOpen(true)}
              onAdvance={advanceJob}
              onCancel={cancelJob}
            />
          )}
          {view === "Work Orders" && (
            <DispatchWorkOrders
              jobs={jobs}
              onFlash={flash}
              onViewJob={(index) => {
                setSelectedJob(index);
                setView("Jobs");
              }}
            />
          )}
          {view === "Payments" && <DispatchPayments jobs={jobs} onFlash={flash} />}
          {view === "GPS Map" && (
            <DispatchMap jobs={jobs} onFlash={flash} onMove={moveJob} />
          )}
          {view === "Analytics" && <DispatchAnalytics onFlash={flash} />}
          {view === "AI Agents" && <DispatchAgents onFlash={flash} />}
          {view === "Equipment" && <DispatchEquipment onFlash={flash} />}
          {view === "Team" && (
            <DispatchTeam
              technicians={technicians}
              onReload={loadTechnicians}
              onTech={() => setRole("Technician")}
              onFlash={flash}
            />
          )}
          {view === "Settings" && <DispatchSettings onFlash={flash} />}
        </div>
      </main>
    </section>
  );
}

type DispatchTechProductivity = {
  id: string;
  name: string;
  hours: number;
  revenueCents: number;
  revenuePerHourCents: number | null;
};
type DispatchAnalytics = {
  bookedThisWeekCents: number;
  collectedCents: number;
  outstandingCents: number;
  outstandingCount: number;
  jobsCompletedThisWeek: number;
  techProductivity: DispatchTechProductivity[];
  profitability: {
    revenueCents: number;
    laborCents: number;
    materialsCents: number;
    profitCents: number;
    marginPct: number;
    jobsIncluded: number;
  };
};
function money(cents: number) {
  return `$${Math.round(cents / 100).toLocaleString()}`;
}
function DispatchDashboard({
  jobs,
  onView,
  onFlash,
  onMove,
  role,
  onReload,
}: {
  jobs: DispatchJob[];
  onView: (view: DispatchView) => void;
  onFlash: (message: string) => void;
  onMove: (index: number, direction: number) => void;
  role: DispatchRole;
  onReload: () => void;
}) {
  const [analytics, setAnalytics] = useState<DispatchAnalytics | null>(null);
  const loadAnalytics = () => {
    void fetch("/api/dispatch/analytics")
      .then((r) => (r.ok ? r.json() : null))
      .then((data: DispatchAnalytics | null) => setAnalytics(data));
  };
  useEffect(loadAnalytics, []);
  const topTechs = (analytics?.techProductivity || []).slice(0, 3);
  const maxRevPerHour = topTechs.reduce((max, t) => Math.max(max, t.revenuePerHourCents || 0), 1);
  const isEmpty = jobs.length === 0;
  const generateBrief = () => {
    const today = jobs.filter((j) => j.status !== "COMPLETE" && j.status !== "INVOICED" && j.status !== "CANCELLED");
    const lines = [
      `Cyncro Dispatch — Daily Brief`,
      `Generated: ${new Date().toLocaleString()}`,
      ``,
      `Booked this week: ${analytics ? money(analytics.bookedThisWeekCents) : "—"}`,
      `Collected: ${analytics ? money(analytics.collectedCents) : "—"}`,
      `Outstanding: ${analytics ? `${money(analytics.outstandingCents)} across ${analytics.outstandingCount} invoice(s)` : "—"}`,
      ``,
      `Open jobs (${today.length}):`,
      ...today.map((j) => `  ${j.time} — ${j.customer} — ${j.service} — ${j.status}${j.tech ? ` — ${j.tech}` : " — unassigned"}`),
    ];
    const blob = new Blob([lines.join("\n")], { type: "text/plain" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `dispatch-brief-${new Date().toISOString().slice(0, 10)}.txt`;
    a.click();
    URL.revokeObjectURL(url);
    onFlash("Daily dispatch brief downloaded");
  };
  const loadDemoData = () => {
    void fetch("/api/dispatch/seed-demo", { method: "POST", headers: { "Content-Type": "application/json" }, body: "{}" })
      .then((r) => r.json()).then((d: { seeded?: boolean; reason?: string }) => {
        if (d.seeded) { onFlash("Demo data loaded — every view now has real sample records"); onReload(); loadAnalytics(); }
        else onFlash(d.reason || "Could not load demo data");
      });
  };
  return (
    <>
      <div className="dispatchPageHead">
        <div>
          <span>LIVE FIELD INTELLIGENCE</span>
          <h1>
            {role === "Owner"
              ? "Your field business, in motion."
              : "Every crew. Every job. Right now."}
          </h1>
          <p>
            Real-time jobs, crews, routes, revenue, and exceptions—one command
            surface.
          </p>
        </div>
        {isEmpty
          ? <button onClick={loadDemoData}>◈ Load demo data</button>
          : <button onClick={generateBrief}>✦ Generate daily brief</button>}
      </div>
      {isEmpty && <p className="disputeEmpty">This workspace is empty. "Load demo data" seeds real sample customers, technicians, and jobs across booked, in-progress, and invoiced-and-paid stages — genuine rows that flow through the same logic as anything you'd enter by hand.</p>}
      <div className="dispatchMetrics">
        {[
          ["BOOKED THIS WEEK", analytics ? money(analytics.bookedThisWeekCents) : "—", "Last 7 days"],
          ["COLLECTED", analytics ? money(analytics.collectedCents) : "—", "Last 7 days"],
          ["OUTSTANDING", analytics ? money(analytics.outstandingCents) : "—", analytics ? `${analytics.outstandingCount} invoices` : ""],
          ["JOBS COMPLETED", analytics ? String(analytics.jobsCompletedThisWeek) : "—", "Last 7 days"],
        ].map((item) => (
          <article key={item[0]}>
            <small>{item[0]}</small>
            <b>{item[1]}</b>
            <span>{item[2]}</span>
          </article>
        ))}
      </div>
      <div className="dispatchDashboardGrid">
        <section className="liveOpsMap dispatchPanel">
          <header>
            <div>
              <small>LIVE JOB MAP</small>
              <h2>{jobs.filter((j) => j.techId).length} assigned · {jobs.length} jobs</h2>
            </div>
            <button onClick={() => onView("GPS Map")}>Full map →</button>
          </header>
          <CyncroMap pins={dispatchPins(jobs)} radar emptyText="Jobs appear here once they have an address we can place on the map." />
          <footer>
            <span><i className="moving" /> In progress</span>
            <span><i className="onsite" /> Assigned</span>
            <span><i className="available" /> Booked</span>
            <b>{jobs.filter((j) => j.lat != null).length} of {jobs.length} placed · tech GPS not connected</b>
          </footer>
        </section>
        <section className="routeCommand dispatchPanel">
          <header>
            <div>
              <small>JOB ORDER · MANUAL</small>
              <h2>Today's run · {Math.min(jobs.length, 3)} jobs</h2>
            </div>
          </header>
          <div className="routeList">
            {jobs.slice(0, 3).map((job, index) => (
              <article key={job.id}>
                <span>{index + 1}</span>
                <div>
                  <b>
                    {job.time} · {job.customer}
                  </b>
                  <small>{job.service}</small>
                </div>
                <em>{job.eta}</em>
                <div>
                  <button onClick={() => onMove(index, -1)}>↑</button>
                  <button onClick={() => onMove(index, 1)}>↓</button>
                </div>
              </article>
            ))}
          </div>
          <button
            className="optimizeRoute"
            onClick={() => onFlash("Automatic route optimization needs a maps/routing integration — reorder manually with ↑↓ for now")}
          >
            ✦ Optimize route now
          </button>
        </section>
        <section className="todayDispatch dispatchPanel">
          <header>
            <div>
              <small>TODAY&apos;S DISPATCH</small>
              <h2>Live job board</h2>
            </div>
            <button onClick={() => onView("Jobs")}>All jobs →</button>
          </header>
          {jobs.map((job) => (
            <button onClick={() => onView("Jobs")} key={job.id}>
              <time>{job.time}</time>
              <i className={job.color} />
              <span>
                <b>{job.customer}</b>
                <small>
                  {job.tech} · {job.service}
                </small>
              </span>
              <em>{job.status}</em>
              <strong>{job.revenue}</strong>
            </button>
          ))}
        </section>
        <section className="techProductivity dispatchPanel">
          <header>
            <div>
              <small>TECH PRODUCTIVITY</small>
              <h2>Revenue per billable hour</h2>
            </div>
            <button onClick={() => onView("Analytics")}>Analyze →</button>
          </header>
          {topTechs.length === 0 && (
            <p className="dispatchPanelEmpty">
              No clocked time yet — productivity appears once techs clock in/out on jobs.
            </p>
          )}
          {topTechs.map((tech) => {
            const initials = tech.name
              .split(" ")
              .map((p) => p[0])
              .join("")
              .slice(0, 2)
              .toUpperCase();
            const pct = tech.revenuePerHourCents
              ? Math.round((tech.revenuePerHourCents / maxRevPerHour) * 100)
              : 0;
            return (
              <div key={tech.id}>
                <i>{initials}</i>
                <span>
                  <b>{tech.name}</b>
                  <small>
                    {tech.revenuePerHourCents ? `${money(tech.revenuePerHourCents)}/hr` : "No hours logged"} · {tech.hours}h
                  </small>
                </span>
                <em>
                  <i style={{ width: `${pct}%` }} />
                </em>
                <strong>{pct}%</strong>
              </div>
            );
          })}
        </section>
        <section className="agentRevenue dispatchPanel">
          <header>
            <div>
              <small>AI AGENT PERFORMANCE · PREVIEW</small>
              <h2>Not yet built for Dispatch</h2>
            </div>
            <button onClick={() => onView("AI Agents")}>Agent center →</button>
          </header>
          <p className="dispatchPanelEmpty">
            Dispatch AI agents (receptionist, setter, follow-up) aren&apos;t built yet — this
            panel will show real agent-attributed revenue once they are.
          </p>
        </section>
        <section className="profitPulse dispatchPanel">
          <header>
            <div>
              <small>PROFITABILITY</small>
              <h2>Live job economics</h2>
            </div>
            <button onClick={() => onView("Analytics")}>Details →</button>
          </header>
          <div className="profitRing">
            <span>
              <b>{analytics ? `${analytics.profitability.marginPct}%` : "—"}</b>
              <small>NET MARGIN</small>
            </span>
          </div>
          <div className="profitFacts">
            <span>
              <small>REVENUE</small>
              <b>{analytics ? money(analytics.profitability.revenueCents) : "—"}</b>
            </span>
            <span>
              <small>LABOR</small>
              <b>{analytics ? money(analytics.profitability.laborCents) : "—"}</b>
            </span>
            <span>
              <small>MATERIALS</small>
              <b>{analytics ? money(analytics.profitability.materialsCents) : "—"}</b>
            </span>
            <span>
              <small>PROFIT</small>
              <b>{analytics ? money(analytics.profitability.profitCents) : "—"}</b>
            </span>
          </div>
          {analytics && analytics.profitability.jobsIncluded === 0 && (
            <p className="dispatchPanelEmpty">Based on completed/invoiced jobs — none yet.</p>
          )}
        </section>
      </div>
    </>
  );
}

function DispatchJobs({
  jobs,
  selected,
  setSelected,
  onFlash,
  onNew,
  onAdvance,
  onCancel,
}: {
  jobs: DispatchJob[];
  selected: number;
  setSelected: (index: number) => void;
  onFlash: (message: string) => void;
  onNew: () => void;
  onAdvance: (index: number) => void;
  onCancel: (index: number) => void;
}) {
  const [statusFilter, setStatusFilter] = useState("ALL");
  const filteredJobs = statusFilter === "ALL" ? jobs : jobs.filter((j) => j.status === statusFilter);
  const job = jobs[selected];
  const [inspectorTab, setInspectorTab] = useState<
    "Overview" | "Notes" | "Photos" | "Time" | "Work order"
  >("Overview");
  const [notes, setNotes] = useState<Record<string, string>[]>([]);
  const [noteDraft, setNoteDraft] = useState("");
  const [clockedIn, setClockedIn] = useState(false);
  const [timeEntries, setTimeEntries] = useState<{ clock_in_at: string; clock_out_at: string | null }[]>([]);
  const [materials, setMaterials] = useState<{ id: string; name: string; quantity: number; unit_cost_cents: number }[]>([]);
  const [materialDraft, setMaterialDraft] = useState({ name: "", quantity: "1", unitCost: "" });
  const reloadJobDetail = () => {
    if (!job) return;
    void fetch(`/api/dispatch/jobs?id=${encodeURIComponent(job.id)}`).then((r) => (r.ok ? r.json() : null)).then((data: { notes?: Record<string, string>[]; time?: { clock_in_at: string; clock_out_at: string | null }[]; materials?: { id: string; name: string; quantity: number; unit_cost_cents: number }[] } | null) => {
      if (!data) return;
      setNotes(data.notes || []);
      setTimeEntries(data.time || []);
      setMaterials(data.materials || []);
      setClockedIn(Boolean((data.time || []).some((t) => !t.clock_out_at)));
    });
  };
  useEffect(reloadJobDetail, [job?.id]);
  const addMaterial = () => {
    if (!job || !materialDraft.name.trim()) return;
    void fetch("/api/dispatch/materials", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ jobId: job.id, name: materialDraft.name.trim(), quantity: Number(materialDraft.quantity) || 1, unitCost: Number(materialDraft.unitCost) || 0 }),
    }).then((r) => {
      if (!r.ok) { onFlash("Unable to add material"); return; }
      setMaterialDraft({ name: "", quantity: "1", unitCost: "" });
      reloadJobDetail();
      onFlash("Material added");
    });
  };
  const removeMaterial = (id: string) => {
    void fetch(`/api/dispatch/materials?id=${encodeURIComponent(id)}`, { method: "DELETE" }).then((r) => {
      if (r.ok) reloadJobDetail();
    });
  };
  const materialsCost = materials.reduce((s, m) => s + m.quantity * m.unit_cost_cents, 0);
  const [profitability, setProfitability] = useState<{ revenueCents: number; materialsCents: number; laborCents: number; profitCents: number } | null>(null);
  useEffect(() => {
    if (!job) return;
    void fetch(`/api/dispatch/invoices?jobId=${encodeURIComponent(job.id)}`).then((r) => (r.ok ? r.json() : null)).then((data: { profitability?: typeof profitability } | null) => {
      if (data) setProfitability(data.profitability || null);
    });
  }, [job?.id, materials, timeEntries]);
  const addNote = () => {
    const clean = noteDraft.trim();
    if (!clean || !job) return;
    void fetch("/api/dispatch/jobs/notes", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ jobId: job.id, body: clean }),
    }).then((r) => {
      if (!r.ok) { onFlash("Unable to save note"); return; }
      setNotes((current) => [{ body: clean, created_at: new Date().toISOString() }, ...current]);
      setNoteDraft("");
      onFlash("Technical note saved to work order");
    });
  };
  const toggleClock = () => {
    if (!job) return;
    void fetch("/api/dispatch/jobs/time", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ jobId: job.id, techId: job.techId }),
    }).then((r) => (r.ok ? r.json() : null)).then((data: { clockedIn?: boolean } | null) => {
      if (!data) { onFlash("Unable to update time entry"); return; }
      setClockedIn(Boolean(data.clockedIn));
      onFlash(data.clockedIn ? "Clocked in" : "Clocked out · labor entry saved");
    });
  };
  if (!job) {
    return (
      <div className="dispatchEmptyState dispatchPanel">
        <small>JOB COMMAND</small>
        <h1>No jobs scheduled</h1>
        <p>Create the first job to begin dispatching your team.</p>
        <button onClick={onNew}>＋ Create job</button>
      </div>
    );
  }
  return (
    <div className="dispatchJobsWorkspace">
      <section className="jobBoard dispatchPanel">
        <header>
          <div>
            <small>JOB COMMAND</small>
            <h1>All field work</h1>
          </div>
          <div>
            <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} aria-label="Filter jobs by status">
              <option value="ALL">All statuses</option>
              {["BOOKED", "ASSIGNED", "IN PROGRESS", "COMPLETE", "INVOICED", "CANCELLED"].map((s) => <option value={s} key={s}>{s}</option>)}
            </select>
            <button onClick={onNew}>＋ Job</button>
          </div>
        </header>
        <div className="jobBoardCols">
          <span>JOB + CUSTOMER</span>
          <span>TECH</span>
          <span>STATUS</span>
          <span>VALUE</span>
        </div>
        {!filteredJobs.length && <p className="disputeEmpty">No jobs match this filter.</p>}
        {filteredJobs.map((item) => {
          const index = jobs.indexOf(item);
          return (
          <button
            className={selected === index ? "active" : ""}
            onClick={() => setSelected(index)}
            key={item.id}
          >
            <span>
              <i>{index + 1}</i>
              <div>
                <b>{item.customer}</b>
                <small>
                  {item.id} · {item.service}
                  <br />
                  {item.address}
                </small>
              </div>
            </span>
            <strong>{item.tech}</strong>
            <em>{item.status}</em>
            <b>{item.revenue}</b>
          </button>
          );
        })}
      </section>
      <aside className="jobInspector dispatchPanel">
        <header>
          <div>
            <small>WORK ORDER</small>
            <h2>{job.id}</h2>
          </div>
        </header>
        <span className="jobStatusLarge">● {job.status}</span>
        <h3>{job.customer}</h3>
        <p>{job.service}</p>
        <address>{job.address}</address>
        <nav className="jobInspectorTabs" aria-label="Job record sections">
          {(["Overview", "Notes", "Photos", "Time", "Work order"] as const).map(
            (tab) => (
              <button
                className={inspectorTab === tab ? "active" : ""}
                onClick={() => setInspectorTab(tab)}
                key={tab}
              >
                {tab}
              </button>
            ),
          )}
        </nav>
        {inspectorTab === "Overview" && (
          <>
            <div className="jobTimeline">
              {["BOOKED", "ASSIGNED", "IN PROGRESS", "COMPLETE", "INVOICED"].map((status) => {
                const lifecycle = ["BOOKED", "ASSIGNED", "IN PROGRESS", "COMPLETE", "INVOICED"];
                const done = lifecycle.indexOf(job.status) >= lifecycle.indexOf(status);
                return (
                  <div className={done ? "done" : ""} key={status}>
                    <i>{done ? "✓" : ""}</i>
                    <span>
                      <b>{status}</b>
                      <small>{status === job.status ? "Current status" : ""}</small>
                    </span>
                  </div>
                );
              })}
            </div>
            <div className="jobEconomics">
              {[
                ["Revenue", job.revenue],
                ["Labor", `$${((profitability?.laborCents ?? 0) / 100).toLocaleString()}`],
                ["Materials", `$${((profitability?.materialsCents ?? materialsCost) / 100).toLocaleString()}`],
                ["Projected profit", `$${((profitability?.profitCents ?? (job.revenueCents - materialsCost)) / 100).toLocaleString()}`],
              ].map((item) => (
                <span key={item[0]}>
                  <small>{item[0]}</small>
                  <b>{item[1]}</b>
                </span>
              ))}
            </div>
            <button onClick={() => onAdvance(selected)}>
              Advance job status
            </button>
            <button className="dangerAction" onClick={() => onCancel(selected)}>
              Cancel job
            </button>
          </>
        )}
        {inspectorTab === "Notes" && (
          <div className="jobRecordPanel">
            <header>
              <div>
                <small>FIELD NOTES</small>
                <b>{notes.length} entries</b>
              </div>
              <span>Visible to office + assigned tech</span>
            </header>
            <div className="jobNotesList">
              {notes.map((note, index) => (
                <article key={note.id || index}>
                  <i>{index + 1}</i>
                  <div>
                    <p>{note.body}</p>
                    <small>
                      {note.author || job.tech} · {note.created_at ? new Date(note.created_at).toLocaleString() : ""}
                    </small>
                  </div>
                </article>
              ))}
              {!notes.length && (
                <p className="emptyRecord">
                  No notes yet. Add diagnostics, work performed, unresolved
                  issues, or next steps.
                </p>
              )}
            </div>
            <textarea
              value={noteDraft}
              onChange={(event) => setNoteDraft(event.target.value)}
              placeholder="Add technical notes, findings, parts used, recommendations…"
            />
            <button onClick={addNote}>＋ Save job note</button>
          </div>
        )}
        {inspectorTab === "Photos" && (
          <div className="jobRecordPanel">
            <header>
              <div>
                <small>JOB DOCUMENTATION</small>
                <b>Photo storage not yet connected</b>
              </div>
              <span>Before · after · serials · test results</span>
            </header>
            <p className="emptyRecord">
              Photo uploads need cloud file storage enabled on this account
              before they can be saved to the job record. This is on the
              roadmap — for now, attach photos to the job note above by
              describing what they show.
            </p>
          </div>
        )}
        {inspectorTab === "Time" && (
          <div className="jobRecordPanel timeClockPanel">
            <header>
              <div>
                <small>TRACKED TIME</small>
                <b>{clockedIn ? "Shift active" : "Not clocked in"}</b>
              </div>
              <span>Labor logged against this job</span>
            </header>
            <div className={`clockHero ${clockedIn ? "active" : ""}`}>
              <span>{clockedIn ? "● LIVE" : "○ READY"}</span>
              <b>
                {(() => {
                  const totalMinutes = timeEntries.reduce((sum, entry) => {
                    if (!entry.clock_out_at) return sum;
                    return sum + (new Date(entry.clock_out_at).getTime() - new Date(entry.clock_in_at).getTime()) / 60000;
                  }, 0);
                  return `${Math.floor(totalMinutes / 60)}h ${Math.round(totalMinutes % 60)}m`;
                })()}
              </b>
              <small>Total labor recorded</small>
            </div>
            <button className="clockAction" onClick={toggleClock}>
              {clockedIn ? "Clock out and save time" : "Clock in to this job"}
            </button>
            <div className="timeEntries">
              {timeEntries.map((entry, index) => (
                <article key={index}>
                  <span>{new Date(entry.clock_in_at).toLocaleString()}</span>
                  <b>{entry.clock_out_at ? `${Math.round((new Date(entry.clock_out_at).getTime() - new Date(entry.clock_in_at).getTime()) / 60000)} min` : "In progress"}</b>
                </article>
              ))}
              {!timeEntries.length && <p className="emptyRecord">No time logged yet.</p>}
            </div>
          </div>
        )}
        {inspectorTab === "Work order" && (
          <div className="jobRecordPanel workOrderDetail">
            <header>
              <div>
                <small>WORK ORDER {job.id}</small>
                <b>Authorized scope</b>
              </div>
              <span>Customer sign-off required</span>
            </header>
            <section>
              <small>SCOPE OF WORK</small>
              <p>
                Diagnose reported issue, complete approved service, test all
                affected systems, document equipment and provide customer
                walkthrough.
              </p>
            </section>
            <div>
              <span>
                <small>SCHEDULE</small>
                <b>Today · {job.time}</b>
              </span>
              <span>
                <small>TECHNICIAN</small>
                <b>{job.tech}</b>
              </span>
              <span>
                <small>AUTHORIZED</small>
                <b>{job.revenue}</b>
              </span>
              <span>
                <small>PO / TERMS</small>
                <b>NET 15</b>
              </span>
            </div>
            <label>
              <input type="checkbox" /> Scope completed and tested
            </label>
            <label>
              <input type="checkbox" /> Required photos and serials uploaded
            </label>
            <label>
              <input type="checkbox" /> Customer/site sign-off obtained
            </label>
            <button
              onClick={() => onFlash("Customer e-signature isn't connected yet — collect it on-site for now")}
            >
              Request customer signature
            </button>
            <section>
              <small>MATERIALS &amp; PARTS</small>
              {materials.map((m) => (
                <div key={m.id} style={{ display: "flex", justifyContent: "space-between", gap: 8, padding: "6px 0" }}>
                  <span>{m.quantity}× {m.name}</span>
                  <span>
                    ${((m.quantity * m.unit_cost_cents) / 100).toLocaleString()}
                    <button onClick={() => removeMaterial(m.id)} style={{ marginLeft: 8 }}>✕</button>
                  </span>
                </div>
              ))}
              {!materials.length && <p className="emptyRecord">No materials logged for this job yet.</p>}
              <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
                <input placeholder="Material name" value={materialDraft.name} onChange={(e) => setMaterialDraft((d) => ({ ...d, name: e.target.value }))} style={{ flex: 2 }} />
                <input placeholder="Qty" type="number" min="0" step="1" value={materialDraft.quantity} onChange={(e) => setMaterialDraft((d) => ({ ...d, quantity: e.target.value }))} style={{ flex: 1 }} />
                <input placeholder="Unit cost $" type="number" min="0" step="0.01" value={materialDraft.unitCost} onChange={(e) => setMaterialDraft((d) => ({ ...d, unitCost: e.target.value }))} style={{ flex: 1 }} />
                <button onClick={addMaterial}>Add</button>
              </div>
            </section>
          </div>
        )}
      </aside>
    </div>
  );
}

function DispatchWorkOrders({
  jobs,
  onFlash,
  onViewJob,
}: {
  jobs: DispatchJob[];
  onFlash: (message: string) => void;
  onViewJob: (index: number) => void;
}) {
  const [status, setStatus] = useState("All");
  return (
    <div className="workOrdersWorkspace">
      <div className="dispatchPageHead">
        <div>
          <span>FIELD DOCUMENT CONTROL</span>
          <h1>Every job, documented and billable.</h1>
          <p>
            Scope, labor, photos, notes, approvals, signatures, and invoice
            readiness in one record.
          </p>
        </div>
        <button onClick={() => onFlash("Create a job from the Jobs tab — every job is its own work order")}>
          ＋ Work order
        </button>
      </div>
      <div className="workOrderMetrics">
        {[
          ["OPEN", String(jobs.filter((j) => !["COMPLETE", "INVOICED", "CANCELLED"].includes(j.status)).length), `${jobs.filter((j) => j.techId && !["COMPLETE", "INVOICED", "CANCELLED"].includes(j.status)).length} assigned`],
          ["AWAITING INVOICE", String(jobs.filter((j) => j.status === "COMPLETE").length), money(jobs.filter((j) => j.status === "COMPLETE").reduce((s, j) => s + j.revenueCents, 0))],
          ["INVOICED", String(jobs.filter((j) => j.status === "INVOICED").length), money(jobs.filter((j) => j.status === "INVOICED").reduce((s, j) => s + j.revenueCents, 0))],
          ["TOTAL VALUE", money(jobs.reduce((s, j) => s + j.revenueCents, 0)), `${jobs.length} job(s)`],
        ].map((metric) => (
          <article className="dispatchPanel" key={metric[0]}>
            <small>{metric[0]}</small>
            <b>{metric[1]}</b>
            <span>{metric[2]}</span>
          </article>
        ))}
      </div>
      <section className="dispatchPanel workOrderCommandTable">
        <header>
          <div>
            <small>WORK ORDER COMMAND</small>
            <h2>Operational records</h2>
          </div>
          <select
            value={status}
            onChange={(event) => setStatus(event.target.value)}
            aria-label="Filter work orders"
          >
            <option>All</option>
            <option>Open</option>
            <option>Ready to invoice</option>
            <option>Complete</option>
          </select>
        </header>
        <div className="workOrderTableHead">
          <span>WORK ORDER</span>
          <span>DOCUMENTATION</span>
          <span>LABOR</span>
          <span>PAYMENT</span>
          <span>READINESS</span>
        </div>
        {jobs.map((job, index) => {
          const ready = index === 0 || job.status === "COMPLETE";
          return (
            <button onClick={() => onViewJob(index)} key={job.id}>
              <span>
                <b>
                  {job.id} · {job.customer}
                </b>
                <small>
                  {job.service}
                  <br />
                  {job.tech}
                </small>
              </span>
              <span>
                <b>{index === 0 ? "6/6 complete" : "3/6 complete"}</b>
                <small>
                  {index === 0
                    ? "Notes · photos · signature"
                    : "Missing photos or sign-off"}
                </small>
              </span>
              <span>
                <b>{index === 0 ? "1h 34m" : "Scheduled"}</b>
                <small>{index === 0 ? "$420 labor" : job.time}</small>
              </span>
              <span>
                <b>{ready ? "Invoice ready" : "Not billed"}</b>
                <small>{job.revenue}</small>
              </span>
              <em className={ready ? "ready" : "attention"}>
                {ready ? "READY" : "ACTION NEEDED"}
              </em>
            </button>
          );
        })}
      </section>
    </div>
  );
}

function DispatchPayments({ jobs, onFlash }: { jobs: DispatchJob[]; onFlash: (message: string) => void }) {
  const [quickBooksConnected, setQuickBooksConnected] = useState(false);
  const [invoices, setInvoices] = useState<Record<string, unknown>[]>([]);
  const loadInvoices = () => {
    void fetch("/api/dispatch/invoices").then((r) => (r.ok ? r.json() : null)).then((data: { invoices?: Record<string, unknown>[] } | null) => {
      if (data?.invoices) setInvoices(data.invoices);
    });
  };
  useEffect(() => { loadInvoices(); }, []);
  const invoicedJobIds = new Set(invoices.map((i) => String(i.job_id)));
  const readyToInvoice = jobs.filter((j) => j.status === "COMPLETE" && !invoicedJobIds.has(j.id));
  const createInvoice = (jobId: string) => {
    void fetch("/api/dispatch/invoices", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ jobId }),
    }).then((r) => {
      if (!r.ok) { onFlash("Unable to create invoice"); return; }
      loadInvoices();
      onFlash("Invoice created");
    });
  };
  const markPaid = (id: string) => {
    void fetch("/api/dispatch/invoices", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ id, markPaid: true }),
    }).then((r) => {
      if (!r.ok) { onFlash("Unable to update invoice"); return; }
      loadInvoices();
      onFlash("Marked as paid");
    });
  };
  const collectedCents = invoices.filter((i) => i.status === "PAID").reduce((s, i) => s + Number(i.amount_cents || 0), 0);
  const outstandingCents = invoices.filter((i) => i.status !== "PAID").reduce((s, i) => s + Number(i.amount_cents || 0), 0);
  return (
    <div className="dispatchPaymentsWorkspace">
      <div className="dispatchPageHead">
        <div>
          <span>REVENUE OPERATIONS</span>
          <h1>From completed work to collected cash.</h1>
          <p>
            Invoices generate from completed jobs and track through payment.
          </p>
        </div>
      </div>
      <div className="paymentMetrics">
        {[
          ["COLLECTED", `$${(collectedCents / 100).toLocaleString()}`, `${invoices.filter((i) => i.status === "PAID").length} invoices`],
          ["OUTSTANDING", `$${(outstandingCents / 100).toLocaleString()}`, `${invoices.filter((i) => i.status !== "PAID").length} invoices`],
          ["READY TO INVOICE", String(readyToInvoice.length), "completed, not yet billed"],
          ["TOTAL INVOICES", String(invoices.length), "all time"],
        ].map((metric) => (
          <article className="dispatchPanel" key={metric[0]}>
            <small>{metric[0]}</small>
            <b>{metric[1]}</b>
            <span>{metric[2]}</span>
          </article>
        ))}
      </div>
      <div className="paymentsGrid">
        <section className="dispatchPanel invoiceCommand">
          <header>
            <div>
              <small>READY TO INVOICE</small>
              <h2>Completed jobs</h2>
            </div>
          </header>
          {readyToInvoice.map((job) => (
            <article key={job.id}>
              <span>
                <b>{job.customer}</b>
                <small>{job.service}</small>
              </span>
              <strong>{job.revenue}</strong>
              <em>COMPLETE</em>
              <button onClick={() => createInvoice(job.id)}>Create invoice</button>
            </article>
          ))}
          {!readyToInvoice.length && <p className="emptyRecord">No completed jobs waiting to be invoiced.</p>}
        </section>
        <section className="dispatchPanel invoiceCommand">
          <header>
            <div>
              <small>INVOICE COMMAND</small>
              <h2>Job payments</h2>
            </div>
          </header>
          {invoices.map((invoice) => (
            <article key={String(invoice.id)}>
              <span>
                <b>{String(invoice.customer_name || "Unknown")}</b>
                <small>{String(invoice.service_type || "")}</small>
              </span>
              <strong>${(Number(invoice.amount_cents || 0) / 100).toLocaleString()}</strong>
              <em>{String(invoice.status)}</em>
              <button onClick={() => markPaid(String(invoice.id))} disabled={invoice.status === "PAID"}>
                {invoice.status === "PAID" ? "Paid" : "Mark paid"}
              </button>
            </article>
          ))}
          {!invoices.length && <p className="emptyRecord">No invoices yet.</p>}
        </section>
        <aside className="dispatchPanel quickBooksCard">
          <header>
            <span className={quickBooksConnected ? "connected" : ""}>QB</span>
            <div>
              <small>ACCOUNTING CONNECTION</small>
              <h2>QuickBooks Online</h2>
            </div>
          </header>
          <p>
            Sync customers, invoices, deposits, taxes, service items, contractor
            labor, materials, and payments without double entry.
          </p>
          <ul>
            <li>✓ Job-to-invoice mapping</li>
            <li>✓ Automatic payment reconciliation</li>
            <li>✓ Expense and material categorization</li>
            <li>✓ Failed-sync review queue</li>
          </ul>
          <div>
            <small>CONNECTION STATUS</small>
            <b>
              {quickBooksConnected
                ? "● Connected · last sync 2 min ago"
                : "○ Ready to connect"}
            </b>
          </div>
          <button
            onClick={() => {
              setQuickBooksConnected(true);
              onFlash("QuickBooks connection demo enabled");
            }}
          >
            {quickBooksConnected
              ? "Run QuickBooks sync"
              : "Connect QuickBooks →"}
          </button>
          <small>
            Live OAuth authorization will activate after credentials are
            configured.
          </small>
        </aside>
      </div>
    </div>
  );
}

